screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#data-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.受験生ID || ""}</td>
        <td>${r.科目名 || ""}</td>
        <td>${r.試験名 || ""}</td>
        <td>${r.実施日 ? new Date(r.実施日).toLocaleDateString() : ""}</td>
        <td>${r.得点 || ""}</td>
        <td>${r.満点 || ""}</td>
        <td>${r.偏差値 || ""}</td>
        <td>${r.順位 || ""}</td>
        <td style="color: ${(r.偏差値差 || 0) >= 0 ? '#27ae60' : '#e74c3c'};">
          ${r.偏差値差 ? (r.偏差値差 > 0 ? '+' : '') + r.偏差値差 : ''}
        </td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  renderRows(tables[2].records || []);

  // 受験生選択肢を設定
  function updateStudentOptions() {
    window.aivicApi.list(2).then(rows => {
      const students = [...new Set(rows.map(r => r.受験生ID).filter(Boolean))];
      const graphSelect = container.querySelector("#select-graph-student");
      const radarSelect = container.querySelector("#select-radar-student");

      [graphSelect, radarSelect].forEach(select => {
        select.innerHTML = '<option value="">受験生を選択</option>' + 
          students.map(id => `<option value="${id}">${id}</option>`).join("");
      });
    });
  }
  updateStudentOptions();

  // 模試日程データを設定
  function updateMockScheduleOptions() {
    if (tables[5] && tables[5].records) {
      const mockSelect = container.querySelector("#select-mock-schedule");
      mockSelect.innerHTML = '<option value="">模試を選択してください</option>' +
        tables[5].records.map(mock => 
          `<option value="${mock.id}">${mock.模試名} (${new Date(mock.実施日).toLocaleDateString()})</option>`
        ).join("");
    }
  }
  updateMockScheduleOptions();

  // 偏差値範囲スライダーの値表示更新
  const rangeMin = container.querySelector("#range-deviation-min");
  const rangeMax = container.querySelector("#range-deviation-max");
  const minValue = container.querySelector("#deviation-min-value");
  const maxValue = container.querySelector("#deviation-max-value");

  rangeMin.addEventListener("input", () => {
    minValue.textContent = rangeMin.value;
    if (parseInt(rangeMin.value) > parseInt(rangeMax.value)) {
      rangeMax.value = rangeMin.value;
      maxValue.textContent = rangeMax.value;
    }
  });

  rangeMax.addEventListener("input", () => {
    maxValue.textContent = rangeMax.value;
    if (parseInt(rangeMax.value) < parseInt(rangeMin.value)) {
      rangeMin.value = rangeMax.value;
      minValue.textContent = rangeMin.value;
    }
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value;
    const startDate = container.querySelector("#date-start").value;
    const endDate = container.querySelector("#date-end").value;
    const subject = container.querySelector("#select-subject").value;
    const minDev = parseInt(rangeMin.value);
    const maxDev = parseInt(rangeMax.value);

    const rows = await window.aivicApi.list(2);
    const filtered = rows.filter(r => {
      if (keyword && !JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())) return false;
      if (startDate && r.実施日 && new Date(r.実施日) < new Date(startDate)) return false;
      if (endDate && r.実施日 && new Date(r.実施日) > new Date(endDate)) return false;
      if (subject && r.科目名 !== subject) return false;
      if (r.偏差値 && (r.偏差値 < minDev || r.偏差値 > maxDev)) return false;
      return true;
    });
    renderRows(filtered);
  });

  // フィルターリセット
  container.querySelector("#btn-reset-filter").addEventListener("click", () => {
    container.querySelector("#input-search").value = "";
    container.querySelector("#date-start").value = "";
    container.querySelector("#date-end").value = "";
    container.querySelector("#select-subject").value = "";
    rangeMin.value = "30";
    rangeMax.value = "80";
    minValue.textContent = "30";
    maxValue.textContent = "80";
    window.aivicApi.list(2).then(renderRows);
  });

  // CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(2);
    const headers = ["受験生ID", "科目名", "試験名", "実施日", "得点", "満点", "偏差値", "順位"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.受験生ID || "",
        r.科目名 || "",
        r.試験名 || "",
        r.実施日 ? new Date(r.実施日).toLocaleDateString() : "",
        r.得点 || "",
        r.満点 || "",
        r.偏差値 || "",
        r.順位 || ""
      ].map(field => `"${field}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "成績データ_" + new Date().toISOString().split('T')[0] + ".csv";
    link.click();
  });

  // 模試結果登録ボタン
  container.querySelector("#btn-mock-register").addEventListener("click", () => {
    const formCard = container.querySelector("#subject-form-card");
    formCard.style.display = formCard.style.display === "none" ? "block" : "none";
  });

  // 予備校成績取得ボタン
  container.querySelector("#btn-prep-school-get").addEventListener("click", () => {
    alert("予備校成績の自動取得機能を実行します。しばらくお待ちください。");
    // 実際の実装では予備校APIやスクレイピング処理を呼び出し
  });

  // 科目別成績保存
  container.querySelector("#btn-save-subject").addEventListener("click", async () => {
    const studentId = container.querySelector("#input-student-id").value;
    const mockId = container.querySelector("#input-mock-id").value;
    const subjectName = container.querySelector("#select-subject-name").value;
    const testDate = container.querySelector("#input-test-date").value;
    const score = container.querySelector("#input-score").value;
    const maxScore = container.querySelector("#input-max-score").value;
    const deviation = container.querySelector("#input-deviation").value;
    const rank = container.querySelector("#input-rank").value;

    if (!studentId || !mockId || !subjectName || !testDate || !score || !maxScore) {
      alert("必須項目を入力してください。");
      return;
    }

    const data = {
      受験生ID: studentId,
      模試ID: mockId,
      科目名: subjectName,
      試験名: `${subjectName}テスト`,
      実施日: testDate,
      得点: parseInt(score),
      満点: parseInt(maxScore),
      偏差値: deviation ? parseFloat(deviation) : null,
      順位: rank ? parseInt(rank) : null,
      科目コード: subjectName,
      試験種別: "模試",
      学年: "高3",
      公開フラグ: true,
      通知済フラグ: false,
      登録日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(2, data);
    if (saved) {
      alert("成績データを保存しました。");
      container.querySelector("#subject-form-card").style.display = "none";
      // フォームリセット
      ["#input-student-id", "#input-mock-id", "#input-test-date", "#input-score", "#input-max-score", "#input-deviation", "#input-rank"].forEach(id => {
        container.querySelector(id).value = "";
      });
      container.querySelector("#select-subject-name").value = "";

      window.aivicApi.list(2).then(renderRows);
      updateStudentOptions();
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel-subject").addEventListener("click", () => {
    container.querySelector("#subject-form-card").style.display = "none";
  });

  // 偏差値推移グラフ描画
  function drawDeviationChart(studentId) {
    const canvas = container.querySelector("#deviation-chart");
    const ctx = canvas.getContext("2d");

    window.aivicApi.list(2).then(rows => {
      const studentData = rows.filter(r => r.受験生ID === studentId && r.偏差値)
        .sort((a, b) => new Date(a.実施日) - new Date(b.実施日));

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      if (studentData.length === 0) {
        ctx.fillStyle = '#6c757d';
        ctx.font = "16px Arial";
        ctx.textAlign = "center";
        ctx.fillText("データがありません", canvas.width / 2, canvas.height / 2);
        return;
      }

      const margin = 60;
      const chartWidth = canvas.width - margin * 2;
      const chartHeight = canvas.height - margin * 2;

      // 軸描画
      ctx.strokeStyle = '#dee2e6';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(margin, margin);
      ctx.lineTo(margin, canvas.height - margin);
      ctx.lineTo(canvas.width - margin, canvas.height - margin);
      ctx.stroke();

      // データポイント描画
      if (studentData.length > 1) {
        ctx.strokeStyle = '#007bff';
        ctx.lineWidth = 2;
        ctx.beginPath();

        studentData.forEach((point, index) => {
          const x = margin + (index / (studentData.length - 1)) * chartWidth;
          const y = canvas.height - margin - ((point.偏差値 - 30) / 50) * chartHeight;

          if (index === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
        });
        ctx.stroke();
      }

      // データポイント
      ctx.fillStyle = '#007bff';
      studentData.forEach((point, index) => {
        const x = margin + (index / Math.max(studentData.length - 1, 1)) * chartWidth;
        const y = canvas.height - margin - ((point.偏差値 - 30) / 50) * chartHeight;

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, 2 * Math.PI);
        ctx.fill();
      });
    });
  }

  // レーダーチャート描画
  function drawRadarChart(studentId) {
    const canvas = container.querySelector("#radar-chart");
    const ctx = canvas.getContext("2d");

    window.aivicApi.list(2).then(rows => {
      const studentData = rows.filter(r => r.受験生ID === studentId && r.偏差値);

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      if (studentData.length === 0) {
        ctx.fillStyle = '#6c757d';
        ctx.font = "16px Arial";
        ctx.textAlign = "center";
        ctx.fillText("データがありません", canvas.width / 2, canvas.height / 2);
        return;
      }

      const subjects = ["国語", "数学", "英語", "理科", "社会"];
      const centerX = canvas.width / 2;
      const centerY = canvas.height / 2;
      const radius = 150;

      // 背景の円描画
      ctx.strokeStyle = '#dee2e6';
      ctx.lineWidth = 1;
      for (let i = 1; i <= 5; i++) {
        ctx.beginPath();
        ctx.arc(centerX, centerY, (radius / 5) * i, 0, 2 * Math.PI);
        ctx.stroke();
      }

      // 軸線描画
      subjects.forEach((subject, index) => {
        const angle = (index * 2 * Math.PI) / subjects.length - Math.PI / 2;
        const x = centerX + Math.cos(angle) * radius;
        const y = centerY + Math.sin(angle) * radius;

        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(x, y);
        ctx.stroke();

        // ラベル
        ctx.fillStyle = '#495057';
        ctx.font = "14px Arial";
        ctx.textAlign = "center";
        ctx.fillText(subject, x + Math.cos(angle) * 20, y + Math.sin(angle) * 20);
      });

      // データプロット
      const subjectScores = {};
      subjects.forEach(subject => {
        const subjectData = studentData.filter(r => r.科目名 === subject);
        if (subjectData.length > 0) {
          subjectScores[subject] = subjectData[subjectData.length - 1].偏差値;
        }
      });

      if (Object.keys(subjectScores).length > 0) {
        ctx.fillStyle = 'rgba(0, 123, 255, 0.2)';
        ctx.strokeStyle = '#007bff';
        ctx.lineWidth = 2;
        ctx.beginPath();

        subjects.forEach((subject, index) => {
          const score = subjectScores[subject] || 50;
          const angle = (index * 2 * Math.PI) / subjects.length - Math.PI / 2;
          const distance = ((score - 30) / 50) * radius;
          const x = centerX + Math.cos(angle) * distance;
          const y = centerY + Math.sin(angle) * distance;

          if (index === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
        });
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
      }
    });
  }

  // グラフ更新イベント
  container.querySelector("#select-graph-student").addEventListener("change", (e) => {
    if (e.target.value) {
      drawDeviationChart(e.target.value);
    }
  });

  container.querySelector("#select-radar-student").addEventListener("change", (e) => {
    if (e.target.value) {
      drawRadarChart(e.target.value);
    }
  });

  // 模試申込ボタン
  container.querySelector("#btn-register-mock").addEventListener("click", () => {
    const selectedMock = container.querySelector("#select-mock-schedule").value;
    if (!selectedMock) {
      alert("模試を選択してください。");
      return;
    }
    alert("選択した模試への申込手続きを開始します。");
  });

  // 行レベル操作（編集・削除）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (deleteBtn) {
      if (!confirm("この成績データを削除しますか？")) return;
      await window.aivicApi.delete(2, deleteBtn.dataset.id);
      window.aivicApi.list(2).then(renderRows);
      updateStudentOptions();
    }

    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(2);
      const record = rows.find(r => r.id === id);
      if (record) {
        container.querySelector("#input-student-id").value = record.受験生ID || "";
        container.querySelector("#input-mock-id").value = record.模試ID || "";
        container.querySelector("#select-subject-name").value = record.科目名|| "";
        container.querySelector("#input-test-date").value = record.実施日 ? record.実施日.split('T')[0] : "";
        container.querySelector("#input-score").value = record.得点 || "";
        container.querySelector("#input-max-score").value = record.満点 || "";
        container.querySelector("#input-deviation").value = record.偏差値 || "";
        container.querySelector("#input-rank").value = record.順位 || "";

        container.querySelector("#subject-form-card").style.display = "block";

        // 保存ボタンを更新モードに変更
        const saveBtn = container.querySelector("#btn-save-subject");
        saveBtn.textContent = "更新";
        saveBtn.onclick = async () => {
          const updatedData = {
            受験生ID: container.querySelector("#input-student-id").value,
            模試ID: container.querySelector("#input-mock-id").value,
            科目名: container.querySelector("#select-subject-name").value,
            実施日: container.querySelector("#input-test-date").value,
            得点: parseInt(container.querySelector("#input-score").value),
            満点: parseInt(container.querySelector("#input-max-score").value),
            偏差値: container.querySelector("#input-deviation").value ? parseFloat(container.querySelector("#input-deviation").value) : null,
            順位: container.querySelector("#input-rank").value ? parseInt(container.querySelector("#input-rank").value) : null,
            更新日時: new Date().toISOString()
          };

          const updated = await window.aivicApi.update(2, id, updatedData);
          if (updated) {
            alert("成績データを更新しました。");
            container.querySelector("#subject-form-card").style.display = "none";
            saveBtn.textContent = "保存";
            saveBtn.onclick = null;
            window.aivicApi.list(2).then(renderRows);
          }
        };
      }
    }
  });
}

function(container, apiUrl, tables) {
  // 統合履歴テーブルの再描画関数
  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#tbody-history");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.統合処理日時 ? new Date(r.統合処理日時).toLocaleString() : ""}</td>
        <td>${r.統合対象期間開始日 ? new Date(r.統合対象期間開始日).toLocaleDateString() : ""} 〜 ${r.統合対象期間終了日 ? new Date(r.統合対象期間終了日).toLocaleDateString() : ""}</td>
        <td>${r.統合処理種別 || ""}</td>
        <td>${r.統合後データ件数 || 0}</td>
        <td>${r.重複データ件数 || 0}</td>
        <td>${r.エラーデータ件数 || 0}</td>
        <td><span style="padding: 4px 8px; border-radius: 4px; background: ${getStatusColor(r.統合処理ステータス)}; color: #ffffff; font-size: 12px;">${r.統合処理ステータス || ""}</span></td>
        <td>${r.実行者種別 || ""}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  function getStatusColor(status) {
    switch(status) {
      case "完了": return "#4CAF50";
      case "処理中": return "#2196F3";
      case "エラー": return "#f44336";
      case "中断": return "#ff9800";
      default: return "#9e9e9e";
    }
  }

  // 予備校データ取得状況の表示
  function renderYobikouStatus() {
    const tbody = container.querySelector("#tbody-yobikou-status");
    const mockData = [
      { name: "河合塾", lastUpdate: "2024-01-15", count: 45, status: "正常" },
      { name: "駿台", lastUpdate: "2024-01-14", count: 38, status: "正常" },
      { name: "東進", lastUpdate: "2024-01-13", count: 52, status: "エラー" },
      { name: "代ゼミ", lastUpdate: "2024-01-12", count: 29, status: "正常" }
    ];

    tbody.innerHTML = mockData.map(d => `
      <tr>
        <td>${d.name}</td>
        <td>${d.lastUpdate}</td>
        <td>${d.count}</td>
        <td><span style="padding: 4px 8px; border-radius: 4px; background: ${d.status === '正常' ? '#4CAF50' : '#f44336'}; color: #ffffff; font-size: 12px;">${d.status}</span></td>
      </tr>
    `).join("");
  }

  // 模試データ取得状況の表示
  function renderMoshiStatus() {
    const tbody = container.querySelector("#tbody-moshi-status");
    const mockData = [
      { name: "全統模試", lastUpdate: "2024-01-15", count: 28, status: "正常" },
      { name: "駿台模試", lastUpdate: "2024-01-14", count: 22, status: "正常" },
      { name: "進研模試", lastUpdate: "2024-01-13", count: 31, status: "正常" },
      { name: "東進模試", lastUpdate: "2024-01-12", count: 19, status: "エラー" }
    ];

    tbody.innerHTML = mockData.map(d => `
      <tr>
        <td>${d.name}</td>
        <td>${d.lastUpdate}</td>
        <td>${d.count}</td>
        <td><span style="padding: 4px 8px; border-radius: 4px; background: ${d.status === '正常' ? '#4CAF50' : '#f44336'}; color: #ffffff; font-size: 12px;">${d.status}</span></td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  window.aivicApi.list(12).then(rows => {
    if (rows) renderHistoryRows(rows);
  });

  renderYobikouStatus();
  renderMoshiStatus();

  // 統合履歴検索
  container.querySelector("#btn-search-history").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search-history").value;
    const rows = await window.aivicApi.list(12);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderHistoryRows(filtered);
    }
  });

  // データ統合実行
  container.querySelector("#btn-integrate").addEventListener("click", async () => {
    const progressContainer = container.querySelector("#progress-container");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");
    const notificationArea = container.querySelector("#notification-area");

    progressContainer.classList.remove("hidden");

    // 統合処理のシミュレーション
    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      progressBar.style.width = progress + "%";
      progressText.textContent = `統合処理中... ${progress}%`;

      if (progress >= 100) {
        clearInterval(interval);
        progressText.textContent = "統合処理完了";

        // 通知表示
        notificationArea.classList.remove("hidden");
        notificationArea.style.background = "rgba(76, 175, 80, 0.08)";
        notificationArea.style.borderLeft = "3px solid #4CAF50";
        notificationArea.innerHTML = `
          <strong>統合完了通知</strong><br>
          データ統合が正常に完了しました。<br>
          統合件数: 164件、重複処理: 12件、エラー: 0件
        `;

        // 統合履歴に新しいレコードを追加
        const newRecord = {
          受験生ID: "sample-student-id",
          統合処理日時: new Date().toISOString(),
          統合対象期間開始日: container.querySelector("#input-start-date").value || new Date(Date.now() - 30*24*60*60*1000).toISOString(),
          統合対象期間終了日: container.querySelector("#input-end-date").value || new Date().toISOString(),
          統合処理種別: "全件統合",
          統合処理ステータス: "完了",
          予備校データ件数: 89,
          模試データ件数: 75,
          統合後データ件数: 164,
          重複データ件数: 12,
          エラーデータ件数: 0,
          実行者種別: "管理者手動",
          通知送信フラグ: true
        };

        window.aivicApi.save(12, newRecord).then(() => {
          window.aivicApi.list(12).then(renderHistoryRows);
        });

        // 重複チェック結果の表示
        showDuplicateResults();

        setTimeout(() => {
          progressContainer.classList.add("hidden");
        }, 3000);
      }
    }, 500);
  });

  // 重複チェック結果の表示
  function showDuplicateResults() {
    const tbody = container.querySelector("#tbody-duplicate");
    const mockDuplicates = [
