        });
      }

      csvContent += "\n\nデータ取得ログ\n";
      csvContent += "実行日時,データソース,処理ステータス,取得件数,エラー件数,処理時間\n";
      if (dataFetchRows) {
        dataFetchRows.forEach(row => {
          csvContent += `"${row.実行開始日時 || ""}","${row.データソース名 || ""}","${row.処理ステータス || ""}","${row.取得件数 || 0}","${row.エラー件数 || 0}","${row.レスポンス時間 || 0}"\n`;
        });
      }

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `system_usage_${new Date().toISOString().split('T')[0]}.csv`;
