function(container, apiUrl, tables) {
  let currentNotifications = [];
  let filteredNotifications = [];

  // 通知アイコンマッピング
  const iconMap = {
    '成績更新': { icon: '📊', class: 'grade' },
    '模試結果': { icon: '📝', class: 'exam' },
    '合格可能性変動': { icon: '🎯', class: 'possibility' },
    '学習助言': { icon: '⚙️', class: 'system' }
  };

  // 通知一覧を再描画する関数
  function renderNotifications(notifications) {
    const container_elem = container.querySelector('#notification-container');

    if (!notifications || notifications.length === 0) {
      container_elem.innerHTML = `
        <div class="empty-state">
          <div class="empty-state-icon">🔔</div>
          <div class="empty-state-message">通知はありません</div>
          <div class="empty-state-submessage">新しい通知が届くとここに表示されます</div>
        </div>
      `;
      return;
    }

    container_elem.innerHTML = notifications.map(notification => {
      const iconInfo = iconMap[notification.通知種別] || { icon: '📢', class: 'system' };
      const isUnread = !notification.既読フラグ;
      const formattedDate = new Date(notification.送信日時).toLocaleString('ja-JP');

      return `
        <div class="notification-item ${isUnread ? 'unread' : ''}" data-id="${notification.通知履歴ID}">
          <input type="checkbox" class="notification-checkbox" data-id="${notification.通知履歴ID}">
          <div class="notification-icon ${iconInfo.class}">
            ${iconInfo.icon}
          </div>
          <div class="notification-content">
            <div class="notification-title">${notification.通知タイトル || ''}</div>
            <div class="notification-meta">
              <span class="notification-date">${formattedDate}</span>
              <span class="notification-category ${iconInfo.class}">${notification.通知種別}</span>
            </div>
            <div class="notification-message">${notification.通知内容 || ''}</div>
            <div class="notification-actions">
              ${notification.関連データ種別 === '模試結果' ? 
                `<a href="#" class="notification-link" data-screen="scr-1778233409974">模試結果を見る</a>` : ''}
              ${notification.関連データ種別 === '成績データ' ? 
                `<a href="#" class="notification-link" data-screen="scr-1778233395300">成績詳細を見る</a>` : ''}
              ${notification.関連データ種別 === '合格可能性' ? 
                `<a href="#" class="notification-link" data-screen="scr-1778233557495">合格可能性を見る</a>` : ''}
            </div>
          </div>
          <div class="notification-item-actions">
            ${isUnread ? '<div class="unread-mark"></div>' : ''}
            <button class="action-btn secondary mark-read-btn" data-id="${notification.通知履歴ID}">
              ${isUnread ? '既読' : '未読'}
            </button>
            <button class="action-btn secondary delete-btn" data-id="${notification.通知履歴ID}">削除</button>
          </div>
        </div>
      `;
    }).join('');

    updateUnreadCount();
