  // 未読件数を更新
  function updateUnreadCount() {
    const unreadCount = filteredNotifications.filter(n => !n.既読フラグ).length;
    container.querySelector('#unread-count').textContent = unreadCount;
  }

  // フィルタリング処理
  function applyFilters() {
    const category = container.querySelector('#filter-category').value;
    const status = container.querySelector('#filter-status').value;
    const dateStart = container.querySelector('#filter-date-start').value;
    const dateEnd = container.querySelector('#filter-date-end').value;

    filteredNotifications = currentNotifications.filter(notification => {
      // カテゴリフィルター
      if (category && notification.通知種別 !== category) return false;

      // ステータスフィルター
      if (status === '未読' && notification.既読フラグ) return false;
      if (status === '既読' && !notification.既読フラグ) return false;

      // 日付フィルター
      const notificationDate = new Date(notification.送信日時);
      if (dateStart && notificationDate < new Date(dateStart)) return false;
      if (dateEnd && notificationDate > new Date(dateEnd + 'T23:59:59')) return false;

      return true;
    });

    renderNotifications(filteredNotifications);
  }

  // CSVエクスポート
  function exportToCSV() {
    const headers = ['通知日時', 'カテゴリ', 'タイトル', '内容', 'ステータス', '優先度'];
    const csvData = filteredNotifications.map(notification => [
      new Date(notification.送信日時).toLocaleString('ja-JP'),
      notification.通知種別 || '',
      notification.通知タイトル || '',
      notification.通知内容 || '',
      notification.既読フラグ ? '既読' : '未読',
      notification.優先度 || ''
    ]);

    const csvContent = '\uFEFF' + [headers, ...csvData]
      .map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(','))
      .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `通知履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データの読み込みと描画
  async function loadNotifications() {
    const notifications = await window.aivicApi.list(1); // 通知履歴テーブル
    if (notifications) {
      currentNotifications = notifications.sort((a, b) => 
        new Date(b.送信日時) - new Date(a.送信日時)
      );
      filteredNotifications = [...currentNotifications];
      renderNotifications(filteredNotifications);
    }
  }

  // 初期データ表示
  if (tables[1] && tables[1].records) {
    currentNotifications = tables[1].records.sort((a, b) => 
      new Date(b.送信日時) - new Date(a.送信日時)
    );
    filteredNotifications = [...currentNotifications];
    renderNotifications(filteredNotifications);
  }

  // イベントリスナーの設定

  // フィルター適用
  container.querySelector('#btn-filter').addEventListener('click', applyFilters);

  // フィルタークリア
  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#filter-category').value = '';
    container.querySelector('#filter-status').value = '';
    container.querySelector('#filter-date-start').value = '';
    container.querySelector('#filter-date-end').value = '';
    filteredNotifications = [...currentNotifications];
    renderNotifications(filteredNotifications);
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

  // 一括既読
  container.querySelector('#btn-mark-all-read').addEventListener('click', async () => {
    const unreadNotifications = filteredNotifications.filter(n => !n.既読フラグ);

    for (const notification of unreadNotifications) {
      await window.aivicApi.update(1, notification.通知履歴ID, {
        既読フラグ: true,
        既読日時: new Date().toISOString()
      });
    }

    await loadNotifications();
  });

  // 選択削除
  container.querySelector('#btn-delete-selected').addEventListener('click', async () => {
    const checkboxes = container.querySelectorAll('.notification-checkbox:checked');
    if (checkboxes.length === 0) {
      alert('削除する通知を選択してください。');
      return;
    }

    if (!confirm(`選択した${checkboxes.length}件の通知を削除しますか？`)) return;

    for (const checkbox of checkboxes) {
      await window.aivicApi.delete(1, checkbox.dataset.id);
    }

    await loadNotifications();
  });

  // 通知設定画面への遷移
  container.querySelector('#btn-notification-settings').addEventListener('click', () => {
    window.showScreen('scr-1778233647948');
  });

  // 通知アイテムのクリックイベント（イベントデリゲーション）
  container.addEventListener('click', async (e) => {
    // 既読/未読切り替え
    const markReadBtn = e.target.closest('.mark-read-btn');
    if (markReadBtn) {
      const id = markReadBtn.dataset.id;
      const notification = currentNotifications.find(n => n.通知履歴ID === id);

      await window.aivicApi.update(1, id, {
        既読フラグ: !notification.既読フラグ,
        既読日時: !notification.既読フラグ ? new Date().toISOString() : null
      });

      await loadNotifications();
      return;
    }

    // 削除
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この通知を削除しますか？')) return;

      await window.aivicApi.delete(1, deleteBtn.dataset.id);
      await loadNotifications();
      return;
    }

    // 関連画面への遷移
    const notificationLink = e.target.closest('.notification-link');
    if (notificationLink) {
      e.preventDefault();
      const screenId = notificationLink.dataset.screen;
      if (screenId) {
        window.showScreen(screenId);
      }
      return;
    }

    // 通知アイテム全体のクリック（既読化）
    const notificationItem = e.target.closest('.notification-item');
    if (notificationItem && !e.target.closest('.notification-checkbox') && 
        !e.target.closest('.notification-item-actions')) {
      const id = notificationItem.dataset.id;
      const notification = currentNotifications.find(n => n.通知履歴ID === id);

      if (!notification.既読フラグ) {
        await window.aivicApi.update(1, id, {
          既読フラグ: true,
          既読日時: new Date().toISOString()
        });

        await loadNotifications();
      }
    }
  });

  // プッシュ通知設定の切り替え
  container.querySelector('#push-notification-toggle').addEventListener('change', async (e) => {
    // 実際の実装では通知設定を更新する処理を追加
    console.log('プッシュ通知設定:', e.target.checked ? '有効' : '無効');
  });

  // 初期データ読み込み
  loadNotifications();
}

