function(container, apiUrl, tables) {
  let currentStudentId = null;
  let judgmentResults = null;

  // 受験生データを取得してドロップダウンに設定
  async function loadStudents() {
    try {
      // 受験生データは志望校登録データから取得
      const aspirationData = await window.aivicApi.list(7); // 志望校登録データ
      const students = {};

      aspirationData.forEach(record => {
        if (record.受験生ID && !students[record.受験生ID]) {
          students[record.受験生ID] = `受験生${record.受験生ID.slice(-8)}`;
        }
      });

      const studentSelect = container.querySelector("#select-student");
      studentSelect.innerHTML = '<option value="">受験生を選択してください</option>';

      Object.entries(students).forEach(([id, name]) => {
        const option = document.createElement("option");
        option.value = id;
        option.textContent = name;
        studentSelect.appendChild(option);
      });
    } catch (error) {
      console.error("受験生データの読み込みに失敗:", error);
    }
  }

  // 模試日程データを取得してドロップダウンに設定
  async function loadMockExams() {
    try {
      const mockExamData = await window.aivicApi.list(6); // 模試日程データ
      const mockExamSelect = container.querySelector("#select-mock-exam");
      mockExamSelect.innerHTML = '<option value="">模試を選択してください</option>';

      const today = new Date();
      const futureExams = mockExamData.filter(exam => {
        const examDate = new Date(exam.実施日);
        return examDate > today;
      }).sort((a, b) => new Date(a.実施日) - new Date(b.実施日));

      futureExams.forEach(exam => {
        const option = document.createElement("option");
        option.value = exam.模試日程ID;
        option.textContent = `${exam.模試名} (${new Date(exam.実施日).toLocaleDateString()})`;
        option.dataset.examDate = exam.実施日;
        mockExamSelect.appendChild(option);
      });
    } catch (error) {
      console.error("模試データの読み込みに失敗:", error);
    }
  }

  // 志望校情報を表示
  async function displaySchoolInfo(studentId) {
    try {
      const aspirationData = await window.aivicApi.list(7); // 志望校登録データ
      const studentAspirations = aspirationData.filter(record => record.受験生ID === studentId);

      const schoolInfoArea = container.querySelector("#school-info-area");

      if (studentAspirations.length === 0) {
        schoolInfoArea.innerHTML = '<p class="muted">志望校が登録されていません</p>';
        return;
      }

      const schoolsHtml = studentAspirations
        .sort((a, b) => a.志望順位 - b.志望順位)
        .map(school => `
          <div style="margin-bottom: 1rem; padding: 0.75rem; border: 1px solid var(--border); border-radius: 4px;">
            <div style="display: flex; justify-content: between; align-items: center;">
              <div>
                <strong>第${school.志望順位}志望: ${school.学校名}</strong>
                ${school.学部名 ? ` ${school.学部名}` : ''}
                ${school.学科名 ? ` ${school.学科名}` : ''}
              </div>
              <div style="text-align: right;">
                <div>必要偏差値: <strong>${school.必要偏差値 || '--'}</strong></div>
                <div class="muted">${school.入試方式}</div>
              </div>
            </div>
          </div>
        `).join('');

      schoolInfoArea.innerHTML = schoolsHtml;
    } catch (error) {
      console.error("志望校情報の取得に失敗:", error);
    }
  }

  // 現在偏差値を取得・表示
  async function displayCurrentDeviation(studentId) {
    try {
      const mockResults = await window.aivicApi.list(2); // 模試結果データ
      const studentResults = mockResults.filter(result => result.受験生ID === studentId);

      if (studentResults.length === 0) {
        container.querySelector("#current-deviation").textContent = "--";
        return;
      }

      // 最新の模試結果を取得
      const latestResult = studentResults.sort((a, b) => new Date(b.受験日) - new Date(a.受験日))[0];
      container.querySelector("#current-deviation").textContent = latestResult.総合偏差値 || "--";
    } catch (error) {
      console.error("現在偏差値の取得に失敗:", error);
    }
  }

  // 目標偏差値を表示
  async function displayTargetDeviation(studentId) {
    try {
      const aspirationData = await window.aivicApi.list(7); // 志望校登録データ
      const firstChoice = aspirationData.find(record => record.受験生ID === studentId && record.志望順位 === 1);

      if (firstChoice && firstChoice.必要偏差値) {
        container.querySelector("#target-deviation").textContent = firstChoice.必要偏差値;
      } else {
        container.querySelector("#target-deviation").textContent = "--";
      }
    } catch (error) {
      console.error("目標偏差値の取得に失敗:", error);
    }
  }

  // 次回模試までの日数を計算・表示
  function updateDaysToExam() {
    const mockExamSelect = container.querySelector("#select-mock-exam");
    const selectedOption = mockExamSelect.options[mockExamSelect.selectedIndex];

    if (selectedOption && selectedOption.dataset.examDate) {
      const examDate = new Date(selectedOption.dataset.examDate);
      const today = new Date();
      const diffTime = examDate - today;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      container.querySelector("#days-to-exam").textContent = diffDays > 0 ? diffDays : 0;
    } else {
      container.querySelector("#days-to-exam").textContent = "--";
    }
  }

  // 優先度判定を実行
  async function executePriorityJudgment() {
    const studentId = container.querySelector("#select-student").value;
    const baseDate = container.querySelector("#input-base-date").value;

    if (!studentId) {
      alert("受験生を選択してください");
      return;
    }

    if (!baseDate) {
      alert("判定基準日付を入力してください");
      return;
    }

    try {
      // 科目別成績データを取得
      const subjectScores = await window.aivicApi.list(3); // 科目別成績データ
      const studentScores = subjectScores.filter(score => score.受験生ID === studentId);

      // 志望校データを取得
      const aspirationData = await window.aivicApi.list(7);
      const firstChoice = aspirationData.find(record => record.受験生ID === studentId && record.志望順位 === 1);

      if (!firstChoice) {
        alert("第一志望校が登録されていません");
        return;
      }

      // 科目別の優先度を計算
      const subjectPriorities = calculateSubjectPriorities(studentScores, firstChoice);

      // 合格可能性を計算
      const passProbability = calculatePassProbability(studentScores, firstChoice);

      // 結果を保存
      judgmentResults = {
        subjectPriorities,
        passProbability,
        studentId,
        baseDate
      };

      // 結果を表示
      displayJudgmentResults();

    } catch (error) {
      console.error("優先度判定の実行に失敗:", error);
      alert("優先度判定の実行に失敗しました");
    }
  }

  // 科目別優先度を計算
  function calculateSubjectPriorities(studentScores, firstChoice) {
    const subjects = ['国語', '数学', '英語', '理科', '社会'];
    const targetDeviation = firstChoice.必要偏差値 || 60;

    return subjects.map((subject, index) => {
      const subjectScore = studentScores.find(score => score.科目名 === subject);
      const currentDeviation = subjectScore ? subjectScore.偏差値 : 40;
      const deviationGap = targetDeviation - currentDeviation;

      // 緊急度レベルを計算（偏差値差に基づく）
      let urgencyLevel = '低';
      let urgencyColor = '#28a745';
      if (deviationGap > 15) {
        urgencyLevel = '最高';
        urgencyColor = '#dc3545';
      } else if (deviationGap > 10) {
        urgencyLevel = '高';
        urgencyColor = '#fd7e14';
      } else if (deviationGap > 5) {
        urgencyLevel = '中';
        urgencyColor = '#ffc107';
      }

      // 推奨学習時間を計算（偏差値差に基づく）
      const recommendedHours = Math.max(2, Math.min(20, deviationGap * 1.5));

      return {
        priority: index + 1,
        subject,
        currentDeviation,
        targetDeviation,
        deviationGap,
        urgencyLevel,
        urgencyColor,
        recommendedHours: Math.round(recommendedHours)
      };
    }).sort((a, b) => b.deviationGap - a.deviationGap)
      .map((item, index) => ({ ...item, priority: index + 1 }));
  }

  // 合格可能性を計算
  function calculatePassProbability(studentScores, firstChoice) {
    const targetDeviation = firstChoice.必要偏差値 || 60;

    if (studentScores.length === 0) {
      return { probability: 0, judgment: 'E' };
    }

    const avgDeviation = studentScores.reduce((sum, score) => sum + (score.偏差値 || 40), 0) / studentScores.length;
    const deviationDiff = avgDeviation - targetDeviation;

    let probability = 50 + (deviationDiff * 3);
    probability = Math.max(0, Math.min(100, probability));

    let judgment = 'C';
    if (probability >= 80) judgment = 'A';
    else if (probability >= 60) judgment = 'B';
    else if (probability >= 40) judgment = 'C';
    else if (probability >= 20) judgment = 'D';
    else judgment = 'E';

    return { probability: Math.round(probability), judgment };
  }

  // 判定結果を表示
  function displayJudgmentResults() {
    if (!judgmentResults) return;

    const { subjectPriorities, passProbability } = judgmentResults;

    // 科目別優先度ランキングを表示
    const tbody = container.querySelector("#priority-ranking-tbody");
    tbody.innerHTML = subjectPriorities.map(item => `
      <tr>
        <td><strong>${item.priority}</strong></td>
        <td>${item.subject}</td>
        <td>${item.currentDeviation}</td>
        <td>${item.targetDeviation}</td>
        <td style="color: ${item.deviationGap > 0 ? '#dc3545' : '#28a745'};">
          ${item.deviationGap > 0 ? '+' : ''}${item.deviationGap}
        </td>
        <td>
          <span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; font-weight: bold; background: ${item.urgencyColor}; color: white;">
            ${item.urgencyLevel}
          </span>
        </td>
        <td>${item.recommendedHours}時間</td>
      </tr>
    `).join('');

    // 合格可能性を表示
    container.querySelector("#pass-probability").textContent = `${passProbability.probability}%`;

    const judgmentElement = container.querySelector("#pass-judgment");
    judgmentElement.textContent = `${passProbability.judgment}判定`;

    let judgmentColor = '#6c757d';
    if (passProbability.judgment === 'A') judgmentColor = '#28a745';
    else if (passProbability.judgment === 'B') judgmentColor = '#17a2b8';
    else if (passProbability.judgment === 'C') judgmentColor = '#ffc107';
    else if (passProbability.judgment === 'D') judgmentColor = '#fd7e14';
    else if (passProbability.judgment === 'E') judgmentColor = '#dc3545';

    judgmentElement.style.background = judgmentColor;
    judgmentElement.style.color = 'white';

    // 学習時間配分グラフを描画
    drawStudyTimeChart(subjectPriorities);

    // 詳細結果を表示
    displayDetailedResults(subjectPriorities, passProbability);
  }

  // 学習時間配分グラフを描画
  function drawStudyTimeChart(priorities) {
    const canvas = container.querySelector("#study-time-chart");
    const ctx = canvas.getContext("2d");

    // Canvas をクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const colors = ['#dc3545', '#fd7e14', '#ffc107', '#28a745', '#17a2b8'];
    const totalHours = priorities.reduce((sum, p) => sum + p.recommendedHours, 0);

    let startAngle = 0;
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 40;

    // 円グラフを描画
    priorities.forEach((priority, index) => {
      const sliceAngle = (priority.recommendedHours / totalHours) * 2 * Math.PI;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.closePath();
      ctx.fillStyle = colors[index % colors.length];
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.stroke();

      // ラベルを描画
      const labelAngle = startAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.7);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.7);

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(priority.subject, labelX, labelY);
      ctx.fillText(`${priority.recommendedHours}h`, labelX, labelY + 15);

      startAngle += sliceAngle;
    });

    // 凡例を描画
    priorities.forEach((priority, index) => {
      const legendY = 20 + index * 25;
      ctx.fillStyle = colors[index % colors.length];
      ctx.fillRect(canvas.width - 150, legendY, 15, 15);

      ctx.fillStyle = '#333333';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(`${priority.subject}: ${priority.recommendedHours}時間/週`, canvas.width - 130, legendY + 12);
    });
  }

  // 詳細結果を表示
  function displayDetailedResults(priorities, passProbability) {
    const detailedResults = container.querySelector("#detailed-results");

    const highPrioritySubjects = priorities.filter(p => p.urgencyLevel === '最高' || p.urgencyLevel === '高');
    const totalGap = priorities.reduce((sum, p) => sum + Math.max(0, p.deviationGap), 0);

    let analysisText = `
      <div style="margin-bottom: 1rem;">
        <h4 style="color: var(--text); margin-bottom: 0.5rem;">分析結果サマリー</h4>
        <p>現在の合格可能性は<strong>${passProbability.probability}%（${passProbability.judgment}判定）</strong>です。</p>
      </div>
    `;

    if (highPrioritySubjects.length > 0) {
      analysisText += `
        <div style="margin-bottom: 1rem; padding: 1rem; border-left: 3px solid #dc3545; background: var(--bg-card);">
          <h5 style="color: var(--text); margin-bottom: 0.5rem;">緊急対策が必要な科目</h5>
          <ul style="margin: 0; padding-left: 1.5rem;">
            ${highPrioritySubjects.map(subject => 
              `<li><strong>${subject.subject}</strong>: 偏差値${subject.deviationGap}ポイント不足（週${subject.recommendedHours}時間の学習を推奨）</li>`
            ).join('')}
          </ul>
        </div>
      `;
    }

    analysisText += `
      <div style="margin-bottom: 1rem; padding: 1rem; border-left: 3px solid #17a2b8; background: var(--bg-card);">
        <h5 style="color: var(--text); margin-bottom: 0.5rem;">学習戦略アドバイス</h5>
        <ul style="margin: 0; padding-left: 1.5rem;">
          <li>最優先科目「${priorities[0].subject}」に週${priorities[0].recommendedHours}時間を集中投下</li>
          <li>偏差値ギャップ合計${totalGap}ポイントの改善が必要</li>
          <li>推奨総学習時間: 週${priorities.reduce((sum, p) => sum + p.recommendedHours, 0)}時間</li>
        </ul>
      </div>
    `;

    if (passProbability.probability < 60) {
      analysisText += `
        <div style="margin-bottom: 1rem; padding: 1rem; border-left: 3px solid #ffc107; background: var(--bg-card);">
          <h5 style="color: var(--text); margin-bottom: 0.5rem;">注意事項</h5>
          <p>現在の合格可能性が60%を下回っています。併願校の検討も含めて戦略を見直すことをお勧めします。</p>
        </div>
      `;
    }

    detailedResults.innerHTML = analysisText;
  }

  // イベントリスナーの設定
  container.querySelector("#select-student").addEventListener("change", async (e) => {
    currentStudentId = e.target.value;
    if (currentStudentId) {
      await displaySchoolInfo(currentStudentId);
      await displayCurrentDeviation(currentStudentId);
      await displayTargetDeviation(currentStudentId);
    } else {
      container.querySelector("#school-info-area").innerHTML = '<p class="muted">受験生を選択すると志望校情報が表示されます</p>';
      container.querySelector("#current-deviation").textContent = "--";
      container.querySelector("#target-deviation").textContent = "--";
    }
  });

  container.querySelector("#select-mock-exam").addEventListener("change", updateDaysToExam);

  container.querySelector("#btn-execute").addEventListener("click", executePriorityJudgment);

  // 基準日付のデフォルト値を今日に設定
  container.querySelector("#input-base-date").value = new Date().toISOString().split('T')[0];

  // 初期データの読み込み
  loadStudents();
  loadMockExams();
  updateDaysToExam();
}

