function(container, apiUrl, tables) {
  let currentData = [];
  let chartScale = 1;
  let activeTab = 'deviation';

  // グラフ描画関数
  function drawChart(data, type = 'deviation') {
    const canvas = container.querySelector('#performance-chart');
    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();

    // Canvas サイズ調整
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = { top: 40, right: 60, bottom: 60, left: 60 };
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    // 背景クリア
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    if (!data || data.length === 0) {
      ctx.fillStyle = '#6b7280';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', width / 2, height / 2);
      return;
    }

    // データの範囲計算
    let yMin, yMax, yLabel;
    if (type === 'deviation') {
      yMin = Math.min(...data.map(d => d.deviation)) - 5;
      yMax = Math.max(...data.map(d => d.deviation)) + 5;
      yLabel = '偏差値';
    } else if (type === 'possibility') {
      yMin = 0;
      yMax = 100;
      yLabel = '合格可能性(%)';
    } else {
      yMin = Math.min(...data.map(d => d.score)) - 20;
      yMax = Math.max(...data.map(d => d.score)) + 20;
      yLabel = '得点';
    }

    // グリッド描画
    ctx.strokeStyle = '#e5e7eb';
    ctx.lineWidth = 1;

    // 横線（Y軸グリッド）
    for (let i = 0; i <= 10; i++) {
      const y = padding.top + (chartHeight / 10) * i;
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(padding.left + chartWidth, y);
      ctx.stroke();

      // Y軸ラベル
      const value = yMax - ((yMax - yMin) / 10) * i;
      ctx.fillStyle = '#374151';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText(Math.round(value), padding.left - 10, y + 4);
    }

    // 縦線（X軸グリッド）
    const xStep = chartWidth / (data.length - 1 || 1);
    for (let i = 0; i < data.length; i++) {
      const x = padding.left + xStep * i;
      ctx.beginPath();
      ctx.moveTo(x, padding.top);
      ctx.lineTo(x, padding.top + chartHeight);
      ctx.stroke();

      // X軸ラベル
      ctx.fillStyle = '#374151';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.save();
      ctx.translate(x, height - padding.bottom + 20);
      ctx.rotate(-Math.PI / 6);
      ctx.fillText(data[i].date, 0, 0);
      ctx.restore();
    }

    // 軸線描画
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(padding.left, padding.top);
    ctx.lineTo(padding.left, padding.top + chartHeight);
    ctx.lineTo(padding.left + chartWidth, padding.top + chartHeight);
    ctx.stroke();

    // 軸ラベル
    ctx.fillStyle = '#374151';
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('実施日', width / 2, height - 10);

    ctx.save();
    ctx.translate(20, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText(yLabel, 0, 0);
    ctx.restore();

    // 合格ラインの描画（偏差値グラフの場合）
    if (type === 'deviation') {
      const targetLine = 65; // 志望校合格ライン
      const lineY = padding.top + chartHeight - ((targetLine - yMin) / (yMax - yMin)) * chartHeight;

      ctx.strokeStyle = '#dc2626';
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      ctx.moveTo(padding.left, lineY);
      ctx.lineTo(padding.left + chartWidth, lineY);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = '#dc2626';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText('合格ライン', padding.left + 10, lineY - 5);
    }

    // データ線の描画
    const getValue = (d) => {
      if (type === 'deviation') return d.deviation;
      if (type === 'possibility') return d.possibility;
      return d.score;
    };

    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 3;
    ctx.beginPath();

    for (let i = 0; i < data.length; i++) {
      const x = padding.left + xStep * i;
      const value = getValue(data[i]);
      const y = padding.top + chartHeight - ((value - yMin) / (yMax - yMin)) * chartHeight;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.stroke();

    // データポイントの描画
    ctx.fillStyle = '#2563eb';
    for (let i = 0; i < data.length; i++) {
      const x = padding.left + xStep * i;
      const value = getValue(data[i]);
      const y = padding.top + chartHeight - ((value - yMin) / (yMax - yMin)) * chartHeight;

      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();

      // データポイントに値を表示
      ctx.fillStyle = '#1f2937';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(Math.round(value), x, y - 10);
      ctx.fillStyle = '#2563eb';
    }
  }

  // サンプルデータ生成
  function generateSampleData() {
    const dates = ['2023/09', '2023/10', '2023/11', '2023/12', '2024/01'];
    return dates.map((date, i) => ({
      date,
      deviation: 60 + Math.random() * 15 + i * 2,
      possibility: 40 + Math.random() * 30 + i * 5,
      score: 400 + Math.random() * 100 + i * 20
    }));
  }

  // 初期データ設定
  currentData = generateSampleData();

  // 初期グラフ描画
  setTimeout(() => {
    drawChart(currentData, activeTab);
  }, 100);

  // タブ切り替え
  container.addEventListener('click', (e) => {
    const tabBtn = e.target.closest('.tab-btn');
    if (tabBtn) {
      // アクティブタブ更新
      container.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
      tabBtn.classList.add('active');

      activeTab = tabBtn.dataset.tab;

      // グラフタイトル更新
      const titles = {
        deviation: '偏差値推移グラフ',
        possibility: '合格可能性推移グラフ',
        score: '得点推移グラフ'
      };
      container.querySelector('#graph-title').textContent = titles[activeTab];

      // グラフ再描画
      drawChart(currentData, activeTab);
    }
  });

  // フィルター適用
  container.querySelector('#btn-apply-filter').addEventListener('click', async () => {
    const period = container.querySelector('#period-select').value;
    const examType = container.querySelector('input[name="exam-type"]:checked').value;

    // 実際の実装では API からフィルタリングされたデータを取得
    // ここではサンプルデータを再生成
    currentData = generateSampleData();
    drawChart(currentData, activeTab);

    // 更新時刻を更新
    const now = new Date();
    container.querySelector('#last-update-time').textContent = 
      `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
  });

  // フィルターリセット
  container.querySelector('#btn-reset-filter').addEventListener('click', () => {
    container.querySelector('#period-select').value = '1year';
    container.querySelector('input[name="exam-type"][value="all"]').checked = true;
    container.querySelector('#subject-all').checked = true;
    container.querySelector('#subject-japanese').checked = false;
    container.querySelector('#subject-math').checked = false;
    container.querySelector('#subject-english').checked = false;
  });

  // ズーム機能
  container.querySelector('#btn-zoom-in').addEventListener('click', () => {
    chartScale = Math.min(chartScale * 1.2, 3);
    drawChart(currentData, activeTab);
  });

  container.querySelector('#btn-zoom-out').addEventListener('click', () => {
    chartScale = Math.max(chartScale / 1.2, 0.5);
    drawChart(currentData, activeTab);
  });

  // PDF出力
  container.querySelector('#btn-pdf-export').addEventListener('click', () => {
    const canvas = container.querySelector('#performance-chart');
    const link = document.createElement('a');
    link.download = `成績推移グラフ_${new Date().toISOString().split('T')[0]}.png`;
    link.href = canvas.toDataURL();
    link.click();
  });

  // データ更新
  container.querySelector('#btn-refresh-data').addEventListener('click', async () => {
    try {
      // 実際の実装では API からデータを再取得
      const data = await window.aivicApi.list(0);
      if (data) {
        currentData = generateSampleData(); // サンプルデータで代替
        drawChart(currentData, activeTab);

        const now = new Date();
        container.querySelector('#last-update-time').textContent = 
          `${now.getFullYear()}/${String(now.getMonth() + 1).padStart(2, '0')}/${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
      }
    } catch (error) {
      console.error('データ更新エラー:', error);
    }
  });

  // ツールチップ機能
  const canvas = container.querySelector('#performance-chart');
  const tooltip = container.querySelector('#chart-tooltip');

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    // データポイントとの距離計算（簡易版）
    const padding = { left: 60, top: 40, right: 60, bottom: 60 };
    const chartWidth = rect.width - padding.left - padding.right;
    const xStep = chartWidth / (currentData.length - 1 || 1);

    let nearestPoint = null;
    let minDistance = Infinity;

    for (let i = 0; i < currentData.length; i++) {
      const pointX = padding.left + xStep * i;
      const distance = Math.abs(x - pointX);

      if (distance < minDistance && distance < 20) {
        minDistance = distance;
        nearestPoint = { index: i, data: currentData[i] };
      }
    }

    if (nearestPoint) {
      const data = nearestPoint.data;
      let value;
      if (activeTab === 'deviation') value = `偏差値: ${Math.round(data.deviation)}`;
      else if (activeTab === 'possibility') value = `合格可能性: ${Math.round(data.possibility)}%`;
      else value = `得点: ${Math.round(data.score)}点`;

      tooltip.innerHTML = `${data.date}<br>${value}`;
      tooltip.style.left = `${e.clientX - rect.left + 10}px`;
      tooltip.style.top = `${e.clientY - rect.top - 10}px`;
      tooltip.style.opacity = '1';
    } else {
      tooltip.style.opacity = '0';
    }
  });

  canvas.addEventListener('mouseleave', () => {
    tooltip.style.opacity = '0';
  });

  // ウィンドウリサイズ対応
  window.addEventListener('resize', () => {
    setTimeout(() => {
      drawChart(currentData, activeTab);
    }, 100);
  });
}

function(container, apiUrl, tables) {
  let currentAnalysisData = null;

  // チャート描画関数
  function drawDeviationTrendChart(canvas, data) {
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const padding = 60;

    ctx.clearRect(0, 0, width, height);

    // 背景
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, width, height);

    // グリッド線
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;

    // Y軸グリッド（偏差値30-80）
    for (let i = 30; i <= 80; i += 10) {
      const y = height - padding - ((i - 30) / 50) * (height - padding * 2);
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(width - padding, y);
      ctx.stroke();

      // Y軸ラベル
      ctx.fillStyle = '#64748b';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText(i.toString(), padding - 10, y + 4);
    }

    // データ線描画
    if (data && data.length > 0) {
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((point, index) => {
        const x = padding + (index / (data.length - 1)) * (width - padding * 2);
        const y = height - padding - ((point.deviation - 30) / 50) * (height - padding * 2);

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();

      // データポイント
      ctx.fillStyle = '#3b82f6';
      data.forEach((point, index) => {
        const x = padding + (index / (data.length - 1)) * (width - padding * 2);
        const y = height - padding - ((point.deviation - 30) / 50) * (height - padding * 2);

        ctx.beginPath();
        ctx.arc(x, y, 4, 0, 2 * Math.PI);
        ctx.fill();
      });
    }

    // 軸ラベル
    ctx.fillStyle = '#374151';
    ctx.font = '14px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('時期', width / 2, height - 10);

    ctx.save();
    ctx.translate(15, height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText('偏差値', 0, 0);
    ctx.restore();
  }

  function drawSubjectRadarChart(canvas, subjects) {
    const ctx = canvas.getContext('2d');
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 60;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景円
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = 1; i <= 5; i++) {
      ctx.beginPath();
      ctx.arc(centerX, centerY, (radius * i) / 5, 0, 2 * Math.PI);
      ctx.stroke();
    }

    // 軸線
    const angleStep = (2 * Math.PI) / subjects.length;
    subjects.forEach((subject, index) => {
      const angle = index * angleStep - Math.PI / 2;
      const x = centerX + Math.cos(angle) * radius;
      const y = centerY + Math.sin(angle) * radius;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.lineTo(x, y);
      ctx.stroke();

      // ラベル
      ctx.fillStyle = '#374151';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      const labelX = centerX + Math.cos(angle) * (radius + 20);
      const labelY = centerY + Math.sin(angle) * (radius + 20);
      ctx.fillText(subject.name, labelX, labelY);
    });

    // データ多角形
    ctx.fillStyle = 'rgba(59, 130, 246, 0.2)';
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();

    subjects.forEach((subject, index) => {
      const angle = index * angleStep - Math.PI / 2;
      const value = Math.max(0, Math.min(1, (subject.deviation - 30) / 50));
      const x = centerX + Math.cos(angle) * radius * value;
      const y = centerY + Math.sin(angle) * radius * value;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  }

  // 分析データ生成（サンプル）
  function generateAnalysisData() {
    return {
      deviationTrend: [
        { date: '2024-01', deviation: 52 },
        { date: '2024-02', deviation: 54 },
        { date: '2024-03', deviation: 56 },
        { date: '2024-04', deviation: 55 },
        { date: '2024-05', deviation: 58 },
        { date: '2024-06', deviation: 60 }
      ],
      subjectRadar: [
        { name: '国語', deviation: 58 },
        { name: '数学', deviation: 62 },
        { name: '英語', deviation: 55 },
        { name: '理科', deviation: 60 },
        { name: '社会', deviation: 57 }
      ],
      admissionProbability: [
        { school: 'A大学', probability: 75, judgment: 'B判定', targetDeviation: 65 },
        { school: 'B大学', probability: 60, judgment: 'C判定', targetDeviation: 62 },
        { school: 'C大学', probability: 85, judgment: 'A判定', targetDeviation: 58 }
      ],
      weaknessRanking: [
        { rank: 1, subject: '英語', current: 55, target: 65, gap: -10, urgency: '高', suggestion: 'リスニング強化' },
        { rank: 2, subject: '社会', current: 57, target: 63, gap: -6, urgency: '中', suggestion: '暗記項目整理' },
        { rank: 3, subject: '国語', current: 58, target: 62, gap: -4, urgency: '中', suggestion: '読解速度向上' }
      ],
      peerComparison: [
        { subject: '国語', own: 58, average: 56, diff: 2, rank: 45, evaluation: '良好' },
        { subject: '数学', own: 62, average: 59, diff: 3, rank: 35, evaluation: '優秀' },
        { subject: '英語', own: 55, average: 58, diff: -3, rank: 65, evaluation: '要改善' }
      ]
    };
  }

  // 分析結果表示
  function displayAnalysisResults(data) {
    currentAnalysisData = data;

    // 総合偏差値推移グラフ
    const deviationCanvas = container.querySelector('#deviation-trend-chart');
    drawDeviationTrendChart(deviationCanvas, data.deviationTrend);

    // 科目別レーダーチャート
    const radarCanvas = container.querySelector('#subject-radar-chart');
    drawSubjectRadarChart(radarCanvas, data.subjectRadar);

    // 志望校合格可能性
    const admissionDiv = container.querySelector('#admission-probability');
    admissionDiv.innerHTML = data.admissionProbability.map(school => `
      <div style="border: 1px solid var(--border); border-radius: 8px; padding: 15px;">
        <h4>${school.school}</h4>
        <div style="display: flex; align-items: center; gap: 10px; margin: 10px 0;">
          <span style="font-size: 24px; font-weight: bold; color: ${school.probability >= 70 ? '#10b981' : school.probability >= 50 ? '#f59e0b' : '#ef4444'};">${school.probability}%</span>
          <span style="padding: 4px 8px; border-radius: 4px; background: ${school.judgment === 'A判定' ? '#dcfce7' : school.judgment === 'B判定' ? '#fef3c7' : '#fee2e2'}; color: var(--text);">${school.judgment}</span>
        </div>
        <p class="muted">目標偏差値: ${school.targetDeviation}</p>
      </div>
    `).join('');

    // 弱点科目ランキング
    const weaknessTbody = container.querySelector('#weakness-ranking');
    weaknessTbody.innerHTML = data.weaknessRanking.map(item => `
      <tr>
        <td>${item.rank}</td>
        <td>${item.subject}</td>
        <td>${item.current}</td>
        <td>${item.target}</td>
        <td style="color: ${item.gap < 0 ? '#ef4444' : '#10b981'};">${item.gap > 0 ? '+' : ''}${item.gap}</td>
        <td><span style="padding: 2px 6px; border-radius: 4px; background: ${item.urgency === '高' ? '#fee2e2' : '#fef3c7'}; color: var(--text);">${item.urgency}</span></td>
        <td>${item.suggestion}</td>
        <td><button class="action-btn secondary subject-detail-btn" data-subject="${item.subject}">詳細</button></td>
      </tr>
    `).join('');

    // 同偏差値帯比較
    const peerTbody = container.querySelector('#peer-comparison');
    peerTbody.innerHTML = data.peerComparison.map(item => `
      <tr>
        <td>${item.subject}</td>
        <td>${item.own}</td>
        <td>${item.average}</td>
        <td style="color: ${item.diff >= 0 ? '#10b981' : '#ef4444'};">${item.diff > 0 ? '+' : ''}${item.diff}</td>
        <td>${item.rank}位</td>
        <td><span style="padding: 2px 6px; border-radius: 4px; background: ${item.evaluation === '優秀' ? '#dcfce7' : item.evaluation === '良好' ? '#fef3c7' : '#fee2e2'}; color: var(--text);">${item.evaluation}</span></td>
      </tr>
    `).join('');
  }

  // CSVエクスポート
  function exportToCSV() {
    if (!currentAnalysisData) return;

    let csvContent = '\uFEFF'; // BOM
    csvContent += '傾向分析結果レポート\n\n';

    // 弱点科目ランキング
    csvContent += '弱点科目ランキング\n';
    csvContent += '順位,科目,現在偏差値,目標偏差値,差分,緊急度,改善提案\n';
    currentAnalysisData.weaknessRanking.forEach(item => {
      csvContent += `${item.rank},${item.subject},${item.current},${item.target},${item.gap},${item.urgency},${item.suggestion}\n`;
    });

    csvContent += '\n同偏差値帯比較\n';
    csvContent += '科目,本人偏差値,同帯平均,差分,順位,評価\n';
    currentAnalysisData.peerComparison.forEach(item => {
      csvContent += `${item.subject},${item.own},${item.average},${item.diff},${item.rank},${item.evaluation}\n`;
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `傾向分析結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  const analyzeBtn = container.querySelector('#btn-analyze');
  analyzeBtn.addEventListener('click', () => {
    const analysisData = generateAnalysisData();
    displayAnalysisResults(analysisData);
  });

  // 科目別詳細分析
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.subject-detail-btn');
    if (detailBtn) {
      const subject = detailBtn.dataset.subject;
