    }
  });

  // エクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', exportToCSV);

  container.querySelector('#btn-export-pdf').addEventListener('click', () => {
    alert('PDF出力機能は開発中です。CSVエクスポートをご利用ください。');
  });

  // 科目チェックボックス制御
  const allCheckbox = container.querySelector('#subject-all');
  const subjectCheckboxes = container.querySelectorAll('[id^="subject-"]:not(#subject-all)');

  allCheckbox.addEventListener('change', () => {
    subjectCheckboxes.forEach(cb => cb.checked = allCheckbox.checked);
  });

  // 初期分析実行
  setTimeout(() => {
    const analysisData = generateAnalysisData();
    displayAnalysisResults(analysisData);
  }, 100);
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#schools-tbody");
