  // 偏差値比較更新関数
  function updateDeviationComparison(targetDeviation) {
    if (!targetDeviation) {
      container.querySelector("#deviation-comparison").style.display = "none";
      return;
    }

    // サンプルの現在偏差値（実際の実装では最新の模試結果から取得）
    const currentDeviation = 58;
    const diff = currentDeviation - parseInt(targetDeviation);

    container.querySelector("#current-deviation").textContent = currentDeviation;
    container.querySelector("#target-deviation").textContent = targetDeviation;

    const diffElement = container.querySelector("#deviation-diff");
    if (diff >= 0) {
      diffElement.textContent = `+${diff}`;
      diffElement.style.color = "#2e7d32";
    } else {
      diffElement.textContent = diff;
      diffElement.style.color = "#d32f2f";
    }

    container.querySelector("#deviation-comparison").style.display = "block";

    // 合格可能性も表示
    updatePossibilityResult(currentDeviation, parseInt(targetDeviation));
  }

  // 合格可能性結果更新関数
  function updatePossibilityResult(current, target) {
    const diff = current - target;
    let percentage, grade, color;

    if (diff >= 5) {
      percentage = 85;
      grade = "A判定";
      color = "#2e7d32";
    } else if (diff >= 2) {
      percentage = 70;
      grade = "B判定";
      color = "#388e3c";
    } else if (diff >= -2) {
      percentage = 50;
      grade = "C判定";
      color = "#f57c00";
    } else if (diff >= -5) {
      percentage = 30;
      grade = "D判定";
      color = "#ff9800";
    } else {
      percentage = 15;
      grade = "E判定";
      color = "#d32f2f";
    }

    container.querySelector("#possibility-percentage").textContent = `${percentage}%`;
    const gradeElement = container.querySelector("#possibility-grade");
    gradeElement.textContent = grade;
    gradeElement.style.backgroundColor = color;
    gradeElement.style.color = "#ffffff";

    container.querySelector("#possibility-result").style.display = "block";
  }

  // 合格可能性算出ボタン
  container.querySelector("#btn-calculate-possibility").addEventListener("click", () => {
    window.showScreen("scr-1778233861021");
  });
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderSchools(schools) {
