            ${w.緊急度レベル >= 3 ? "高" : w.緊急度レベル >= 2 ? "中" : "低"}
          </span>
        </td>
      </tr>
    `).join("");
  }

  function drawSubjectChart(subjectData) {
    const canvas = container.querySelector("#subject-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!subjectData || subjectData.length === 0) {
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "14px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("データがありません", canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = 40;
    const chartWidth = canvas.width - margin * 2;
    const chartHeight = canvas.height - margin * 2;
    const barWidth = chartWidth / subjectData.length;

    // Y軸（偏差値30-80）
    ctx.strokeStyle = "#e5e7eb";
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = margin + (chartHeight * i) / 5;
      ctx.beginPath();
      ctx.moveTo(margin, y);
      ctx.lineTo(margin + chartWidth, y);
      ctx.stroke();

      ctx.fillStyle = "#9fb0d1";
      ctx.font = "12px sans-serif";
      ctx.textAlign = "right";
      ctx.fillText((80 - i * 10).toString(), margin - 5, y + 4);
    }

    // 棒グラフ
    subjectData.forEach((subject, index) => {
      const x = margin + index * barWidth;
      const deviation = subject.現在偏差値 || 50;
      const barHeight = ((deviation - 30) / 50) * chartHeight;
      const y = margin + chartHeight - barHeight;

      ctx.fillStyle = "#3b82f6";
      ctx.fillRect(x + barWidth * 0.1, y, barWidth * 0.8, barHeight);

      // 科目名
      ctx.fillStyle = "#374151";
      ctx.font = "11px sans-serif";
      ctx.textAlign = "center";
      ctx.save();
      ctx.translate(x + barWidth / 2, margin + chartHeight + 15);
      ctx.rotate(-Math.PI / 6);
      ctx.fillText(subject.科目名 || "", 0, 0);
      ctx.restore();

      // 偏差値表示
      ctx.fillStyle = "#1f2937";
      ctx.font = "10px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(deviation.toString(), x + barWidth / 2, y - 5);
    });
  }

  function drawComparisonChart(schoolData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!schoolData || schoolData.length === 0) {
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "14px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("データがありません", canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = 40;
    const chartWidth = canvas.width - margin * 2;
    const chartHeight = canvas.height - margin * 2;
    const barHeight = chartHeight / schoolData.length;

    schoolData.forEach((school, index) => {
      const y = margin + index * barHeight;
      const required = school.必要偏差値 || 60;
      const current = school.現在偏差値 || 50;

      // 必要偏差値バー（背景）
      const requiredWidth = ((required - 30) / 50) * chartWidth;
      ctx.fillStyle = "#e5e7eb";
      ctx.fillRect(margin, y + barHeight * 0.2, requiredWidth, barHeight * 0.3);

      // 現在偏差値バー
      const currentWidth = ((current - 30) / 50) * chartWidth;
      ctx.fillStyle = current >= required ? "#10b981" : "#ef4444";
      ctx.fillRect(margin, y + barHeight * 0.5, currentWidth, barHeight * 0.3);

      // 学校名
      ctx.fillStyle = "#374151";
      ctx.font = "11px sans-serif";
      ctx.textAlign = "left";
      ctx.fillText(school.学校名 || "", margin + chartWidth + 5, y + barHeight * 0.6);
    });
  }

  function drawHistoryChart(historyData) {
    const canvas = container.querySelector("#history-chart");
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!historyData || historyData.length === 0) {
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "14px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("データがありません", canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = 40;
    const chartWidth = canvas.width - margin * 2;
    const chartHeight = canvas.height - margin * 2;

    // 折れ線グラフ
    ctx.strokeStyle = "#3b82f6";
    ctx.lineWidth = 2;
    ctx.beginPath();

    historyData.forEach((point, index) => {
      const x = margin + (index / (historyData.length - 1)) * chartWidth;
      const possibility = point.合格可能性パーセント || 0;
      const y = margin + chartHeight - (possibility / 100) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = "#3b82f6";
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.stroke();
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
