      const headers = ["受験生ID", "算出日時", "総合偏差値", "合格可能性パーセント", "合格可能性判定", "算出方式", "信頼度"];
      const csvContent = [
        headers.join(","),
        ...results.map(r => [
          r.受験生ID || "",
          r.算出日時 || "",
          r.総合偏差値 || "",
          r.合格可能性パーセント || "",
          r.合格可能性判定 || "",
          r.算出方式 || "",
          r.信頼度 || ""
        ].map(field => `"${field}"`).join(","))
      ].join("\n");

      const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `合格可能性評価結果_${new Date().toISOString().slice(0, 10)}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("CSVエクスポートエラー:", error);
    }
  });
}

function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderComparison(rows) {
    const tbody = container.querySelector("#tbody-comparison");
    const selectTargetSchool = container.querySelector("#select-target-school");

    tbody.innerHTML = rows.map(row => {
      const currentDeviation = getCurrentDeviation(row.受験生ID);
      const deviationDiff = currentDeviation - (row.必要偏差値 || 0);
      const possibility = calculatePossibility(deviationDiff);
      const judgment = getJudgment(possibility);
      const requiredImprovement = deviationDiff < 0 ? Math.abs(deviationDiff) : 0;

      const statusColor = getStatusColor(judgment);

      return `
        <tr data-id="${row.id}">
          <td>${row.志望順位 || '-'}</td>
          <td>${row.学校名 || ''}</td>
          <td>${(row.学部名 || '') + (row.学科名 ? '・' + row.学科名 : '')}</td>
          <td>${row.入試方式 || ''}</td>
          <td>${row.必要偏差値 || '-'}</td>
          <td>${currentDeviation}</td>
          <td style="color: ${deviationDiff >= 0 ? '#2563eb' : '#dc2626'}">${deviationDiff > 0 ? '+' : ''}${deviationDiff}</td>
          <td>${possibility}%</td>
          <td><span style="background: ${statusColor}; color: white; padding: 2px 8px; border-radius: 12px; font-size: 0.8em;">${judgment}</span></td>
          <td>${requiredImprovement > 0 ? requiredImprovement : '-'}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id}">詳細</button>
            <button class="action-btn secondary delete-btn" data-id="${row.id}">削除</button>
          </td>
        </tr>
      `;
    }).join("");

    // 対象校選択肢を更新
    selectTargetSchool.innerHTML = '<option value="">学校を選択してください</option>' +
      rows.map(row => `<option value="${row.id}">${row.学校名}${row.学部名 ? '・' + row.学部名 : ''}</option>`).join("");
  }

  // 現在偏差値を取得（模擬データ）
  function getCurrentDeviation(studentId) {
    return Math.floor(Math.random() * 20) + 50; // 50-70の範囲でランダム
  }

  // 合格可能性を計算
  function calculatePossibility(deviationDiff) {
    if (deviationDiff >= 10) return 85;
    if (deviationDiff >= 5) return 70;
    if (deviationDiff >= 0) return 55;
    if (deviationDiff >= -5) return 35;
    if (deviationDiff >= -10) return 20;
    return 10;
  }

  // 判定を取得
  function getJudgment(possibility) {
    if (possibility >= 80) return 'A判定';
    if (possibility >= 60) return 'B判定';
    if (possibility >= 40) return 'C判定';
    if (possibility >= 20) return 'D判定';
    return 'E判定';
  }

  // ステータス色を取得
  function getStatusColor(judgment) {
    switch (judgment) {
      case 'A判定': return '#059669';
      case 'B判定': return '#0891b2';
      case 'C判定': return '#ea580c';
      case 'D判定': return '#dc2626';
      case 'E判定': return '#991b1b';
      default: return '#6b7280';
    }
  }

  // 科目別比較グラフを描画
  function drawSubjectChart(schoolId) {
    const canvas = container.querySelector("#chart-subject-comparison");
    const ctx = canvas.getContext("2d");

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!schoolId) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('学校を選択してください', canvas.width / 2, canvas.height / 2);
      return;
    }

    const subjects = ['国語', '数学', '英語', '理科', '社会'];
    const currentScores = [65, 58, 72, 61, 55]; // 現在偏差値（模擬データ）
    const requiredScores = [70, 65, 75, 68, 60]; // 必要偏差値（模擬データ）

    const margin = 60;
    const chartWidth = canvas.width - margin * 2;
    const chartHeight = canvas.height - margin * 2;
    const barWidth = chartWidth / subjects.length / 2 - 10;

    // 背景
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // グリッド線
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 10; i++) {
      const y = margin + (chartHeight * i / 10);
      ctx.beginPath();
      ctx.moveTo(margin, y);
      ctx.lineTo(canvas.width - margin, y);
      ctx.stroke();
    }

    // Y軸ラベル
    ctx.fillStyle = '#475569';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 10; i++) {
      const value = 80 - (i * 5);
      const y = margin + (chartHeight * i / 10);
      ctx.fillText(value.toString(), margin - 10, y + 4);
    }

    // 棒グラフを描画
    subjects.forEach((subject, index) => {
      const x = margin + (chartWidth / subjects.length) * index + 20;
      const currentHeight = (currentScores[index] - 30) / 50 * chartHeight;
      const requiredHeight = (requiredScores[index] - 30) / 50 * chartHeight;

      // 現在偏差値（青）
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(x, margin + chartHeight - currentHeight, barWidth, currentHeight);

      // 必要偏差値（赤）
      ctx.fillStyle = '#ef4444';
      ctx.fillRect(x + barWidth + 5, margin + chartHeight - requiredHeight, barWidth, requiredHeight);

      // 科目名
      ctx.fillStyle = '#1e293b';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(subject, x + barWidth, canvas.height - margin + 20);

      // 数値表示
      ctx.fillStyle = '#475569';
      ctx.font = '10px sans-serif';
      ctx.fillText(currentScores[index].toString(), x + barWidth/2, margin + chartHeight - currentHeight - 5);
      ctx.fillText(requiredScores[index].toString(), x + barWidth + 5 + barWidth/2, margin + chartHeight - requiredHeight - 5);
    });

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(margin, 20, 15, 15);
    ctx.fillStyle = '#1e293b';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('現在偏差値', margin + 20, 32);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(margin + 100, 20, 15, 15);
    ctx.fillText('必要偏差値', margin + 120, 32);
  }

  // 詳細分析を表示
  function showDetailedAnalysis(schoolId) {
    const analysisContent = container.querySelector("#analysis-content");

    if (!schoolId) {
      analysisContent.innerHTML = '<p class="muted">志望校を選択すると詳細な分析結果が表示されます</p>';
      return;
    }

    analysisContent.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 1rem;">
        <div style="border-left: 3px solid #3b82f6; background: var(--bg-card); padding: 1rem;">
          <h4>総合評価</h4>
          <p>現在の成績では<strong>C判定</strong>です。あと偏差値<strong>5ポイント</strong>の向上でB判定に到達できます。</p>
        </div>
        <div style="border-left: 3px solid #f59e0b; background: var(--bg-card); padding: 1rem;">
          <h4>重点強化科目</h4>
          <p><strong>数学</strong>と<strong>理科</strong>の偏差値向上が合格への近道です。特に数学は7ポイントの向上が必要です。</p>
        </div>
        <div style="border-left: 3px solid #10b981; background: var(--bg-card); padding: 1rem;">
          <h4>学習推奨事項</h4>
          <p>過去問演習を重点的に行い、苦手分野の基礎固めを優先してください。月1回の模試受験をお勧めします。</p>
        </div>
        <div style="border-left: 3px solid #8b5cf6; background: var(--bg-card); padding: 1rem;">
          <h4>合格予測</h4>
          <p>現在のペースで学習を続けた場合、<strong>6ヶ月後</strong>にB判定到達の可能性が高いです。</p>
        </div>
      </div>
    `;
  }

  // CSVエクスポート
  function exportToCSV() {
    window.aivicApi.list(8).then(rows => {
      if (!rows) return;

      const headers = ['志望順位', '学校名', '学部名', '学科名', '入試方式', '必要偏差値', '現在偏差値', '偏差値差分', '合格可能性', '判定'];
      const csvData = [headers.join(',')];

      rows.forEach(row => {
        const currentDeviation = getCurrentDeviation(row.受験生ID);
        const deviationDiff = currentDeviation - (row.必要偏差値 || 0);
        const possibility = calculatePossibility(deviationDiff);
        const judgment = getJudgment(possibility);

        const csvRow = [
          row.志望順位 || '',
          `"${row.学校名 || ''}"`,
          `"${row.学部名 || ''}"`,
          `"${row.学科名 || ''}"`,
          `"${row.入試方式 || ''}"`,
          row.必要偏差値 || '',
          currentDeviation,
          deviationDiff,
          possibility,
          judgment
        ];
        csvData.push(csvRow.join(','));
      });

      const blob = new Blob(['\uFEFF' + csvData.join('\n')], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '志望校合格ライン比較_' + new Date().toISOString().split('T')[0] + '.csv';
      link.click();
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(8).then(rows => {
    if (rows) renderComparison(rows);
  });

  // 絞り込みボタン
  container.querySelector("#btn-filter").addEventListener("click", () => {
    const mockType = container.querySelector("#select-mock-type").value;
    const startDate = container.querySelector("#input-date-start").value;
    const endDate = container.querySelector("#input-date-end").value;
    const possibilityFilter = container.querySelector("#select-possibility-filter").value;

    window.aivicApi.list(8).then(rows => {
      if (!rows) return;

      let filteredRows = rows;

      if (mockType) {
        filteredRows = filteredRows.filter(row => row.模試種別 === mockType);
      }

      if (possibilityFilter) {
        filteredRows = filteredRows.filter(row => {
          const currentDeviation = getCurrentDeviation(row.受験生ID);
          const deviationDiff = currentDeviation - (row.必要偏差値 || 0);
          const possibility = calculatePossibility(deviationDiff);
          const judgment = getJudgment(possibility);

          switch (possibilityFilter) {
            case 'A': return judgment === 'A判定';
            case 'B': return ['A判定', 'B判定'].includes(judgment);
            case 'C': return ['A判定', 'B判定', 'C判定'].includes(judgment);
            case 'D': return ['A判定', 'B判定', 'C判定', 'D判定'].includes(judgment);
            default: return true;
          }
        });
      }

      renderComparison(filteredRows);
    });
  });

  // 条件リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#select-mock-type").value = "";
    container.querySelector("#input-date-start").value = "";
    container.querySelector("#input-date-end").value = "";
    container.querySelector("#select-possibility-filter").value = "";
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = true);

    window.aivicApi.list(8).then(rows => {
      if (rows) renderComparison(rows);
    });
  });

  // 志望校追加ボタン
  container.querySelector("#btn-add-school").addEventListener("click", () => {
    container.querySelector("#modal-add-school").style.display = "block";
  });

  // モーダル関連
  container.querySelector("#btn-cancel-add").addEventListener("click", () => {
    container.querySelector("#modal-add-school").style.display = "none";
  });

  container.querySelector("#btn-save-school").addEventListener("click", async () => {
    const schoolData = {
      学校名: container.querySelector("#input-school-name").value,
      学部名: container.querySelector("#input-department").value,
      学科名: container.querySelector("#input-major").value,
      入試方式: container.querySelector("#select-exam-type").value,
      志望順位: parseInt(container.querySelector("#select-priority").value),
      必要偏差値: parseInt(container.querySelector("#input-required-deviation").value),
      受験生ID: "sample-student-id",
      登録日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      削除フラグ: false
    };

    const saved = await window.aivicApi.save(8, schoolData);
    if (saved) {
      container.querySelector("#modal-add-school").style.display = "none";
      // フォームリセット
      container.querySelector("#input-school-name").value = "";
      container.querySelector("#input-department").value = "";
      container.querySelector("#input-major").value = "";
      container.querySelector("#input-required-deviation").value = "";

      window.aivicApi.list(8).then(rows => {
        if (rows) renderComparison(rows);
      });
    }
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export-csv").addEventListener("click", exportToCSV);

  // データ更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", () => {
    window.aivicApi.list(8).then(rows => {
      if (rows) renderComparison(rows);
    });
  });

  // 対象校選択
  container.querySelector("#select-target-school").addEventListener("change", (e) => {
    const schoolId = e.target.value;
    drawSubjectChart(schoolId);
    showDetailedAnalysis(schoolId);
  });

  // 行レベル操作（削除・詳細）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この志望校を削除しますか？")) return;
      await window.aivicApi.delete(8, deleteBtn.dataset.id);
      window.aivicApi.list(8).then(rows => {
        if (rows) renderComparison(rows);
      });
      return;
    }

    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const schoolId = detailBtn.dataset.id;
      container.querySelector("#select-target-school").value = schoolId;
      drawSubjectChart(schoolId);
      showDetailedAnalysis(schoolId);
    }
  });

  // 初期グラフ描画
  drawSubjectChart(null);
}

