  // 受験生選択肢を描画
  function renderStudentOptions() {
    const select = container.querySelector('#select-student');
    select.innerHTML = '<option value="">受験生を選択してください</option>';

    studentsData.forEach(student => {
      const option = document.createElement('option');
      option.value = student.id;
      option.textContent = `${student.name} (${student.grade})`;
      select.appendChild(option);
    });
  }

  // 成績詳細を表示
  function displayStudentDetail(studentId) {
    currentStudentId = studentId;
    const student = studentsData.find(s => s.id === studentId);
    if (!student) return;

    // 基本情報表示
    container.querySelector('#student-name').textContent = student.name;

    // 最新の模試結果を取得
    const latestMockResult = mockResultsData
      .filter(m => m.受験生ID === studentId)
      .sort((a, b) => new Date(b.受験日) - new Date(a.受験日))[0];

    if (latestMockResult) {
      container.querySelector('#test-info').textContent = 
        `${latestMockResult.模試名} - ${new Date(latestMockResult.受験日).toLocaleDateString()}`;
      container.querySelector('#total-deviation').textContent = 
        `偏差値 ${latestMockResult.総合偏差値 || '--'}`;
      container.querySelector('#total-score').textContent = 
        `総合得点 ${latestMockResult.総合得点 || '--'}点`;
      container.querySelector('#national-rank').textContent = 
        `${latestMockResult.全国順位 || '--'}位`;
      container.querySelector('#school-rank').textContent = 
        `${latestMockResult.都道府県順位 || '--'}位`;
    }

    // 科目別成績表示
    renderSubjectScores(studentId);

    // グラフ描画
    renderSubjectChart(studentId);
    renderTrendChart(studentId);

    // 志望校合格可能性表示
    renderAdmissionPossibility(studentId);

    // 弱点科目・分析コメント表示
    renderWeakSubjects(studentId);
    renderAnalysisComment(studentId);

    // 詳細エリアを表示
    container.querySelector('#detail-content').classList.remove('hidden');
  }

  // 科目別成績テーブル描画
  function renderSubjectScores(studentId) {
    const tbody = container.querySelector('#subject-scores-tbody');
    const studentSubjects = subjectScoresData.filter(s => s.受験生ID === studentId);

    tbody.innerHTML = studentSubjects.map(subject => {
      const scoreRate = subject.満点 ? Math.round((subject.得点 / subject.満点) * 100) : 0;
      const prevComparison = subject.偏差値差 ? 
        (subject.偏差値差 > 0 ? `+${subject.偏差値差}` : `${subject.偏差値差}`) : '--';
      const targetAchieved = subject.目標達成フラグ ? '達成' : '未達成';
      const targetClass = subject.目標達成フラグ ? 'success' : 'warning';

      return `
        <tr>
          <td>${subject.科目名 || '--'}</td>
          <td>${subject.得点 || '--'}</td>
          <td>${subject.満点 || '--'}</td>
          <td>${scoreRate}%</td>
          <td>${subject.偏差値 || '--'}</td>
          <td>${subject.順位 || '--'}</td>
          <td style="color: ${subject.偏差値差 > 0 ? '#32cd32' : subject.偏差値差 < 0 ? '#ff6b6b' : 'var(--text)'}">${prevComparison}</td>
          <td><span class="badge ${targetClass}">${targetAchieved}</span></td>
        </tr>
      `;
    }).join('');
  }

  // 科目別偏差値グラフ描画
  function renderSubjectChart(studentId) {
    const canvas = container.querySelector('#subject-chart');
    const ctx = canvas.getContext('2d');
    const studentSubjects = subjectScoresData.filter(s => s.受験生ID === studentId);

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (studentSubjects.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = 40;
    const chartWidth = canvas.width - margin * 2;
    const chartHeight = canvas.height - margin * 2;
    const barWidth = chartWidth / studentSubjects.length;

    // Y軸（偏差値30-80）
    ctx.strokeStyle = '#e1e8ed';
    ctx.lineWidth = 1;
    for (let i = 30; i <= 80; i += 10) {
      const y = margin + chartHeight - ((i - 30) / 50) * chartHeight;
      ctx.beginPath();
      ctx.moveTo(margin, y);
      ctx.lineTo(margin + chartWidth, y);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px Arial';
      ctx.textAlign = 'right';
      ctx.fillText(i.toString(), margin - 5, y + 4);
    }

    // 棒グラフ描画
    studentSubjects.forEach((subject, index) => {
      const deviation = subject.偏差値 || 50;
      const barHeight = ((deviation - 30) / 50) * chartHeight;
      const x = margin + index * barWidth + barWidth * 0.2;
      const y = margin + chartHeight - barHeight;

      ctx.fillStyle = deviation >= 60 ? '#32cd32' : deviation >= 50 ? '#4a90e2' : '#ff6b6b';
      ctx.fillRect(x, y, barWidth * 0.6, barHeight);

      // 科目名
      ctx.fillStyle = '#2c3e50';
      ctx.font = '11px Arial';
      ctx.textAlign = 'center';
      ctx.save();
      ctx.translate(x + barWidth * 0.3, margin + chartHeight + 15);
      ctx.rotate(-Math.PI / 4);
      ctx.fillText(subject.科目名 || '', 0, 0);
      ctx.restore();

      // 偏差値表示
      ctx.fillStyle = '#2c3e50';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(deviation.toString(), x + barWidth * 0.3, y - 5);
    });
  }

  // 偏差値推移チャート描画
  function renderTrendChart(studentId) {
    const canvas = container.querySelector('#trend-chart');
    const ctx = canvas.getContext('2d');
    const historyData = deviationHistoryData
      .filter(h => h.受験生ID === studentId)
      .sort((a, b) => new Date(a.測定日) - new Date(b.測定日));

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (historyData.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('推移データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    const margin = 40;
    const chartWidth = canvas.width - margin * 2;
    const chartHeight = canvas.height - margin * 2;

    // Y軸（偏差値30-80）
    ctx.strokeStyle = '#e1e8ed';
    ctx.lineWidth = 1;
    for (let i = 30; i <= 80; i += 10) {
      const y = margin + chartHeight - ((i - 30) / 50) * chartHeight;
      ctx.beginPath();
      ctx.moveTo(margin, y);
      ctx.lineTo(margin + chartWidth, y);
      ctx.stroke();

      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px Arial';
      ctx.textAlign = 'right';
      ctx.fillText(i.toString(), margin - 5, y + 4);
    }

    // 折れ線グラフ描画
    if (historyData.length > 1) {
      ctx.strokeStyle = '#4a90e2';
      ctx.lineWidth = 2;
      ctx.beginPath();

      historyData.forEach((point, index) => {
        const x = margin + (index / (historyData.length - 1)) * chartWidth;
        const y = margin + chartHeight - ((point.偏差値 - 30) / 50) * chartHeight;

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });

      ctx.stroke();

      // データポイント
      historyData.forEach((point, index) => {
        const x = margin + (index / (historyData.length - 1)) * chartWidth;
        const y = margin + chartHeight - ((point.偏差値 - 30) / 50) * chartHeight;

        ctx.fillStyle = '#4a90e2';
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();

        // 日付表示
        ctx.fillStyle = '#2c3e50';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        const date = new Date(point.測定日).toLocaleDateString();
        ctx.fillText(date, x, margin + chartHeight + 20);
      });
    }
  }

  // 志望校合格可能性表示
  function renderAdmissionPossibility(studentId) {
    const container_elem = container.querySelector('#admission-possibility');
    const possibilities = admissionPossibilityData.filter(a => a.受験生ID === studentId);

    if (possibilities.length === 0) {
      container_elem.innerHTML = '<p style="color: var(--text-muted);">志望校データがありません</p>';
      return;
    }

    container_elem.innerHTML = possibilities.map(poss => {
      const percentage = poss.合格可能性パーセント || 0;
      const judgment = poss.合格可能性判定 || 'E判定';
      const judgmentColor = judgment.includes('A') ? '#32cd32' : 
                           judgment.includes('B') ? '#4a90e2' : 
                           judgment.includes('C') ? '#ffa500' : '#ff6b6b';

      return `
        <div style="padding: 15px; margin-bottom: 10px; background: var(--bg-card); border-radius: 6px; border-left: 4px solid ${judgmentColor};">
          <div style="display: flex; justify-content: space-between; align-items: center;">
            <div>
              <div style="font-weight: bold; color: var(--text);">第${poss.志望順位 || '?'}志望校</div>
              <div style="color: var(--text-muted); font-size: 14px;">偏差値差: ${poss.偏差値差分 || '--'}</div>
            </div>
            <div style="text-align: right;">
              <div style="font-size: 18px; font-weight: bold; color: ${judgmentColor};">${judgment}</div>
              <div style="color: var(--text-muted);">${percentage}%</div>
            </div>
          </div>
        </div>
      `;
    }).join('');
  }

  // 弱点科目表示
  function renderWeakSubjects(studentId) {
    const container_elem = container.querySelector('#weak-subjects');
    const analyses = subjectAnalysisData.filter(a => a.受験生ID === studentId);

    if (analyses.length === 0) {
      container_elem.innerHTML = '<p style="color: var(--text-muted);">分析データがありません</p>';
      return;
    }

    const weakSubjects = analyses.filter(a => a.緊急度レベル >= 3);

    if (weakSubjects.length === 0) {
      container_elem.innerHTML = '<p style="color: var(--text);">特に注意が必要な科目はありません</p>';
      return;
    }

    container_elem.innerHTML = weakSubjects.map(subject => {
      const urgencyColor = subject.緊急度レベル === 4 ? '#ff6b6b' : '#ffa500';

      return `
        <div style="padding: 10px; margin-bottom: 8px; background: rgba(255,107,107,0.08); border-left: 3px solid ${urgencyColor}; border-radius: 4px;">
          <div style="font-weight: bold; color: var(--text);">${subject.科目名}</div>
          <div style="font-size: 12px; color: var(--text-muted);">弱点分野: ${subject.弱点分野1 || '未分析'}</div>
          <div style="font-size: 12px; color: var(--text-muted);">得点率: ${subject.弱点分野1得点率 || '--'}%</div>
        </div>
      `;
    }).join('');
  }

  // 分析コメント表示
  function renderAnalysisComment(studentId) {
    const container_elem = container.querySelector('#analysis-comment');
    const analyses = subjectAnalysisData.filter(a => a.受験生ID === studentId);

    if (analyses.length === 0) {
      container_elem.innerHTML = '<p style="color: var(--text-muted);">分析コメントがありません</p>';
      return;
    }

    const latestAnalysis = analyses.sort((a, b) => new Date(b.分析実行日時) - new Date(a.分析実行日時))[0];

    container_elem.innerHTML = `
      <div style="padding: 15px; background: var(--bg-card); border-radius: 6px;">
        <div style="color: var(--text); line-height: 1.6;">
          ${latestAnalysis.保護者向けコメント || '総合的な学習状況は良好です。継続して学習を進めてください。'}
        </div>
        <div style="margin-top: 10px; font-size: 12px; color: var(--text-muted);">
          分析日時: ${new Date(latestAnalysis.分析実行日時).toLocaleString()}
        </div>
      </div>
    `;
  }

  // 詳細表示ボタンイベント
  container.querySelector('#btn-load-detail').addEventListener('click', () => {
    const studentId = container.querySelector('#select-student').value;
    if (!studentId) {
      alert('受験生を選択してください');
      return;
    }
    displayStudentDetail(studentId);
  });

  // 前回比較の計算と表示
  function updateComparisonResult(studentId) {
    const mockResults = mockResultsData
      .filter(m => m.受験生ID === studentId)
      .sort((a, b) => new Date(b.受験日) - new Date(a.受験日));

    if (mockResults.length >= 2) {
      const latest = mockResults[0];
      const previous = mockResults[1];
      const diff = (latest.総合偏差値 || 0) - (previous.総合偏差値 || 0);

      let comparisonText = '';
      let comparisonColor = 'var(--text)';

      if (diff > 0) {
        comparisonText = `前回より +${diff}`;
        comparisonColor = '#32cd32';
      } else if (diff < 0) {
        comparisonText = `前回より ${diff}`;
        comparisonColor = '#ff6b6b';
      } else {
        comparisonText = '前回と同じ';
      }

      const elem = container.querySelector('#comparison-result');
      elem.textContent = comparisonText;
      elem.style.color = comparisonColor;
    } else {
      container.querySelector('#comparison-result').textContent = '比較データなし';
    }
  }

  // 初期化
  loadAllData();
}

function(container, apiUrl, tables) {
  // 合格可能性データの再描画関数
  function renderPossibilityRows(rows) {
    const tbody = container.querySelector("#possibility-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.志望順位 || ""}</td>
        <td>${r.学校名 || ""}</td>
        <td>${r.学部名 || ""}${r.学科名 ? "・" + r.学科名 : ""}</td>
        <td>
          <div style="width: 100px; background: #f1f5f9; border-radius: 4px; overflow: hidden;">
            <div style="width: ${r.合格可能性パーセント || 0}%; height: 20px; background: ${(r.合格可能性パーセント || 0) >= 80 ? '#22c55e' : (r.合格可能性パーセント || 0) >= 60 ? '#f59e0b' : '#ef4444'}; display: flex; align-items: center; justify-content: center; color: white; font-size: 0.8rem;">
              ${r.合格可能性パーセント || 0}%
            </div>
          </div>
        </td>
        <td>
          <span style="padding: 0.25rem 0.5rem; border-radius: 4px; font-size: 0.8rem; font-weight: bold; 
                       background: ${r.合格可能性判定 === 'A判定' ? '#22c55e' : r.合格可能性判定 === 'B判定' ? '#3b82f6' : r.合格可能性判定 === 'C判定' ? '#f59e0b' : '#ef4444'}; 
                       color: white;">
            ${r.合格可能性判定 || ""}
          </span>
        </td>
        <td>${r.志望校合格ライン偏差値 || ""}</td>
        <td>${r.総合偏差値 || ""}</td>
        <td style="color: ${(r.偏差値差分 || 0) >= 0 ? '#22c55e' : '#ef4444'};">
          ${(r.偏差値差分 || 0) >= 0 ? '+' : ''}${r.偏差値差分 || 0}
        </td>
      </tr>
    `).join("");
  }

  // タブ切り替え機能
  function setupTabs() {
    const tabBtns = container.querySelectorAll(".tab-btn");
    const tabContents = container.querySelectorAll(".tab-content");

    tabBtns.forEach(btn => {
      btn.addEventListener("click", () => {
        // アクティブタブの切り替え
        tabBtns.forEach(b => b.classList.remove("active"));
        btn.classList.add("active");

        // コンテンツの表示切り替え
        tabContents.forEach(content => content.classList.add("hidden"));
        const targetTab = btn.dataset.tab;
        const targetContent = container.querySelector(`#content-${targetTab}`);
        if (targetContent) {
          targetContent.classList.remove("hidden");
        }
      });
    });
  }

  // 偏差値推移グラフの描画
  function drawTrendChart() {
    const canvas = container.querySelector("#trend-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const months = ["10月", "11月", "12月", "1月", "2月", "3月"];
    const deviationData = [58, 61, 63, 65, 67, 65];
    const targetLine = 70;

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = "#e2e8f0";
    ctx.lineWidth = 1;

    // Y軸
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.stroke();

    // X軸
    ctx.beginPath();
    ctx.moveTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 目標ライン
    const targetY = canvas.height - padding - ((targetLine - 50) / 30) * chartHeight;
    ctx.strokeStyle = "#ef4444";
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(padding, targetY);
    ctx.lineTo(canvas.width - padding, targetY);
    ctx.stroke();
    ctx.setLineDash([]);

    // 偏差値ライン
    ctx.strokeStyle = "#3b82f6";
    ctx.lineWidth = 3;
    ctx.beginPath();

    deviationData.forEach((value, index) => {
      const x = padding + (index / (deviationData.length - 1)) * chartWidth;
      const y = canvas.height - padding - ((value - 50) / 30) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = "#3b82f6";
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
    });
    ctx.stroke();

    // ラベル
    ctx.fillStyle = "#64748b";
    ctx.font = "12px sans-serif";
    ctx.textAlign = "center";

    // X軸ラベル
    months.forEach((month, index) => {
      const x = padding + (index / (months.length - 1)) * chartWidth;
      ctx.fillText(month, x, canvas.height - padding + 20);
    });

    // Y軸ラベル
    ctx.textAlign = "right";
    for (let i = 50; i <= 80; i += 5) {
      const y = canvas.height - padding - ((i - 50) / 30) * chartHeight;
      ctx.fillText(i.toString(), padding - 10, y + 4);
    }

    // 目標ラインラベル
    ctx.fillStyle = "#ef4444";
    ctx.textAlign = "left";
    ctx.fillText("目標偏差値", canvas.width - padding + 10, targetY + 4);
  }

  // レーダーチャートの描画
  function drawRadarChart() {
    const canvas = container.querySelector("#radar-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 80;

    const subjects = ["国語", "数学", "英語", "理科", "社会"];
    const scores = [65, 58, 72, 61, 68];
    const maxScore = 80;

    // 背景グリッド
    ctx.strokeStyle = "#e2e8f0";
    ctx.lineWidth = 1;

    for (let i = 1; i <= 4; i++) {
      const r = (radius / 4) * i;
      ctx.beginPath();
      ctx.arc(centerX, centerY, r, 0, 2 * Math.PI);
      ctx.stroke();
    }

    // 軸線
    subjects.forEach((_, index) => {
      const angle = (index * 2 * Math.PI) / subjects.length - Math.PI / 2;
      const x = centerX + Math.cos(angle) * radius;
      const y = centerY + Math.sin(angle) * radius;

      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.lineTo(x, y);
      ctx.stroke();
    });

    // データエリア
    ctx.fillStyle = "rgba(59, 130, 246, 0.2)";
    ctx.strokeStyle = "#3b82f6";
    ctx.lineWidth = 2;
    ctx.beginPath();

    scores.forEach((score, index) => {
      const angle = (index * 2 * Math.PI) / subjects.length - Math.PI / 2;
      const r = (score / maxScore) * radius;
      const x = centerX + Math.cos(angle) * r;
      const y = centerY + Math.sin(angle) * r;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // データポイント
    ctx.fillStyle = "#3b82f6";
    scores.forEach((score, index) => {
      const angle = (index * 2 * Math.PI) / subjects.length - Math.PI / 2;
      const r = (score / maxScore) * radius;
      const x = centerX + Math.cos(angle) * r;
      const y = centerY + Math.sin(angle) * r;

      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
    });

    // ラベル
    ctx.fillStyle = "#374151";
    ctx.font = "14px sans-serif";
    ctx.textAlign = "center";

    subjects.forEach((subject, index) => {
      const angle = (index * 2 * Math.PI) / subjects.length - Math.PI / 2;
      const x = centerX + Math.cos(angle) * (radius + 30);
      const y = centerY + Math.sin(angle) * (radius + 30);

      ctx.fillText(subject, x, y + 4);

      // スコア表示
      ctx.fillStyle = "#6b7280";
      ctx.font = "12px sans-serif";
      ctx.fillText(scores[index].toString(), x, y + 20);
      ctx.fillStyle = "#374151";
      ctx.font = "14px sans-serif";
    });
  }

  // 初期データ読み込みと描画
  async function loadInitialData() {
    try {
      const possibilityData = await window.aivicApi.list(7); // 合格可能性算出結果
      if (possibilityData) {
        renderPossibilityRows(possibilityData);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
    }
  }

  // 分析実行
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const period = container.querySelector("#period-select").value;
    const examType = container.querySelector('input[name="exam-type"]:checked').value;
    const subjects = Array.from(container.querySelectorAll('.subject-item:checked')).map(cb => cb.value);

    // 分析処理（実際の実装では API 呼び出し）
    container.querySelector("#btn-analyze").textContent = "分析中...";
    container.querySelector("#btn-analyze").disabled = true;

    setTimeout(() => {
      // グラフ再描画
      drawTrendChart();
      drawRadarChart();

      // サマリー更新
      container.querySelector("#summary-deviation").textContent = "65.2";
      container.querySelector("#summary-deviation-diff").textContent = "+2.3";
      container.querySelector("#data-update-time").textContent = `最終更新: ${new Date().toLocaleString()}`;

      container.querySelector("#btn-analyze").textContent = "分析実行";
      container.querySelector("#btn-analyze").disabled = false;

      alert("分析が完了しました");
    }, 2000);
  });

  // エクスポート機能
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const data = await window.aivicApi.list(7);
      if (!data) return;

      const headers = ["志望順位", "学校名", "学部名", "学科名", "合格可能性", "判定", "必要偏差値", "現在偏差値"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...data.map(row => [
          row.志望順位 || "",
          row.学校名 || "",
          row.学部名 || "",
          row.学科名 || "",
          row.合格可能性パーセント || "",
          row.合格可能性判定 || "",
          row.志望校合格ライン偏差値 || "",
          row.総合偏差値 || ""
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `成績分析結果_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert("エクスポートに失敗しました");
    }
  });

  // 分析結果表示画面への遷移
  container.querySelector("#btn-show-results").addEventListener("click", () => {
    window.showScreen("scr-1778235576529");
  });

  // 科目選択の全選択制御
  container.querySelector("#subject-all").addEventListener("change", (e) => {
    const subjectItems = container.querySelectorAll(".subject-item");
    subjectItems.forEach(item => {
      item.checked = e.target.checked;
    });
  });

  // 初期化
  setupTabs();
  loadInitialData();

  // 初期グラフ描画
  setTimeout(() => {
    drawTrendChart();
    drawRadarChart();
  }, 100);
}
